def _check_deprecation_details(self):
    if self.system_check_removed_details is not None:
        details = self.system_check_removed_details
        default_id = "fields.EXXX"
        default_msg = (
            "%s has been removed except for support in historical migrations."
        )
        check_class = checks.Error
    elif self.system_check_deprecated_details is not None:
        details = self.system_check_deprecated_details
        default_id = "fields.WXXX"
        default_msg = "%s has been deprecated."
        check_class = checks.Warning
    else:
        return []
    return [
        check_class(
            details.get("msg", default_msg % self.__class__.__name__),
            hint=details.get("hint"),
            obj=self,
            id=details.get("id", default_id),
        )
    ]
